package org.brightstats.stats;

import java.util.*;
import java.nio.file.*;
import com.google.gson.*;

public final class OrdinalChecks {
    static int checks;
    static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Unsupported ordinal input accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(args[0]);Files.createDirectories(out);for(double rho:new double[]{-.99,-.8,0,.5,.99})require(Math.abs(Polychoric.bivariate(0,0,rho)-(.25+Math.asin(rho)/(2*Math.PI)))<1e-10,"Independent orthant-probability identity");double[] thresholds={-2,-.5,.1,2};double mass=0;for(int a=0;a<5;a++)for(int b=0;b<5;b++)mass+=Polychoric.cell(Polychoric.bound(thresholds,a-1),Polychoric.bound(thresholds,a),Polychoric.bound(thresholds,b-1),Polychoric.bound(thresholds,b),.9);require(Math.abs(mass-1)<1e-11,"Ordinal cell probabilities sum to one");
        int n=1400;int[][] codes=new int[n][6];Random rng=new Random(551947);double[] lambda={1,.8,1.1,1,.9,.7},cuts={-1.2,-.3,.3,1.2};for(var row:codes){double x=rng.nextGaussian(),y=.5*x+Math.sqrt(.95)*rng.nextGaussian();for(int j=0;j<6;j++){double response=lambda[j]*(j<3?x:y)+rng.nextGaussian();int level=0;while(level<cuts.length&&response>cuts[level])level++;row[j]=level;}}
        var names=List.of("X1","X2","X3","Y1","Y2","Y3");List<List<String>> levels=new ArrayList<>();for(int j=0;j<6;j++)levels.add(List.of("Strongly disagree","Disagree","Neutral","Agree","Strongly agree"));var blocks=List.of(new PlsSem.Block("X",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{3,4,5},PlsSem.Mode.A));var prepared=OrdinalSem.reflective(names,blocks,List.of(new PlsSem.Edge(0,1)));var fit=OrdinalSem.fit(codes,names,levels,prepared.model(),OrdinalSem.Options.defaults());require(fit.converged()&&fit.locallyIdentified(),"Ordinal DWLS model regularity");require(fit.degreesOfFreedom()==8&&Double.isFinite(fit.adjustedPValue())&&fit.scalingFactor()>0,"Full-Gamma scaled/shifted fit test");require(fit.moments().pairs().size()==15,"All source response-correlation pairs");
        for(int j=0;j<6;j++)for(int k=0;k<4;k++){double sd=Math.sqrt(1+lambda[j]*lambda[j]*(j<3?1:1.2));require(Math.abs(fit.moments().thresholds()[j][k]-cuts[k]/sd)<.14,"Known latent-response threshold recovery");}
        var work=new OrdinalSem.Work(prepared.model(),fit.moments());double[] theta=prepared.model().parameters().stream().mapToDouble(p->p.start()/p.scale()).toArray();var point=work.evaluate(theta);for(int j=0;j<theta.length;j++){double[] a=theta.clone(),b=theta.clone();a[j]+=1e-6;b[j]-=1e-6;double derivative=(work.evaluate(a).value()-work.evaluate(b).value())/2e-6;require(Math.abs(derivative-point.gradient()[j])<1e-6,"Ordinal correlation-model analytic gradient");}
        int[][] invalid=Arrays.stream(codes).map(int[]::clone).toArray(int[][]::new);invalid[0][0]=99;reject(()->OrdinalSem.fit(invalid,names,levels,prepared.model(),OrdinalSem.Options.defaults()));var duplicate=List.of("X1","X1","X3","Y1","Y2","Y3");reject(()->Polychoric.fit(codes,duplicate,levels,5));Thread.currentThread().interrupt();try{OrdinalSem.fit(codes,names,levels,prepared.model(),OrdinalSem.Options.defaults());throw new AssertionError("Ordinal cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}
        int[][] binary=new int[200][2];for(int i=0;i<200;i++){binary[i][0]=i%2;binary[i][1]=(i/2)%2;}var tetra=Polychoric.fit(binary,List.of("A","B"),List.of(List.of("No","Yes"),List.of("No","Yes")),5);require(Math.abs(tetra.correlation()[0][1])<1e-7&&Math.abs(tetra.momentCovariance()[0][0]-Math.PI*Math.PI/4)<1e-7,"Independent balanced tetrachoric influence variance identity");int[][] duplicates=Arrays.stream(binary).map(int[]::clone).toArray(int[][]::new);for(var row:duplicates)row[1]=row[0];reject(()->Polychoric.fit(duplicates,List.of("A","B"),List.of(List.of("No","Yes"),List.of("No","Yes")),5));
        Gson gson=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();JsonObject record=new JsonObject();record.add("codes",gson.toJsonTree(codes));record.add("fit",gson.toJsonTree(fit));record.add("blocks",gson.toJsonTree(blocks));record.add("edges",gson.toJsonTree(List.of(new PlsSem.Edge(0,1))));record.addProperty("checks",checks);Files.writeString(out.resolve("cases.json"),gson.toJson(record));System.out.println("Ordinal checks: "+checks);
    }
}
